curl -s -X POST https://slack.com/api/users.list \
  -d "token=<TOKEN>" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for m in data['members']:
        name = m.get('name','')
        real = m.get('real_name','')
        if 'robert' in name.lower() or 'robert' in real.lower():
            print(m['id'], name, real, m.get('is_admin'), m.get('is_owner'))
else:
    print(data)
"
